public class NDXLoggerSecurityInformationClass 
    extends NDXLogger
    implements NDXILogger
{
    NDXLoggerSecurityInformationTable nDXLoggerSecurityInformationTable;
    NDXLoggerSecurityInformationLine nDXLoggerSecurityInformationLine;



}

Method.Source:
 /// <summary>
 /// PaffH 10.12.21
 /// </summary>
 /// <param name = "_startWithTitle">str</param>
/// <returns>NDXLoggerSecurityInformationClass</returns>
 public static NDXLoggerSecurityInformationClass construct(str _startWithTitle = '')
 {
     NDXLoggerSecurityInformationClass nDXLoggerSecurityInformationClass = new NDXLoggerSecurityInformationClass();
     if (!prmIsDefault(_startWithTitle))
     {
         NDXArgsLoggerSecuritiyInformation argsLogger = new NDXArgsLoggerSecuritiyInformation();
         argsLogger.parmLogTitle(_startWithTitle);
         nDXLoggerSecurityInformationClass.Start(argsLogger);
     }

     return nDXLoggerSecurityInformationClass;
 }

/// <summary>
/// PaffH 10.12.21
/// </summary>
/// <param name = "_argsLogger">NDXArgsLoggerSecuritiyInformation</param>
/// <returns>Common</returns>
public Common Start(NDXIArgsLogger _argsLogger)
{
    NDXArgsLoggerSecuritiyInformation argsLogger = _argsLogger as NDXArgsLoggerSecuritiyInformation;
    userConnection.ttsbegin();

    nDXLoggerSecurityInformationTable.setConnection(userConnection);
    nDXLoggerSecurityInformationTable.selectForUpdate(true);
    nDXLoggerSecurityInformationTable.LogTitle = argsLogger.parmLogTitle();
    nDXLoggerSecurityInformationTable.Start = DateTimeUtil::utcNow();
    nDXLoggerSecurityInformationTable.insert();

    userConnection.ttscommit();
    return nDXLoggerSecurityInformationTable;
}

/// <summary>
/// PaffH 10.12.21
/// </summary>
/// <param name = "_argsLogger">NDXArgsLoggerSecuritiyInformation</param>
public void End(NDXIArgsLogger _argsLogger = new NDXArgsLoggerSecuritiyInformation())
{
    userConnection.ttsbegin();

    nDXLoggerSecurityInformationTable.setConnection(userConnection);
    nDXLoggerSecurityInformationTable.End = DateTimeUtil::utcNow();
    nDXLoggerSecurityInformationTable.update();

    userConnection.ttscommit();
}

/// <summary>
/// PaffH 10.12.21
/// </summary>
/// <param name = "_argsLogger">NDXArgsLoggerSecuritiyInformation</param>
void LogLineCreate(NDXIArgsLogger _argsLogger)
{
    NDXArgsLoggerSecuritiyInformation argsLogger = _argsLogger as NDXArgsLoggerSecuritiyInformation;
    userConnection.ttsbegin();

    nDXLoggerSecurityInformationLine.setConnection(userConnection);
    nDXLoggerSecurityInformationLine.selectForUpdate(true);
    nDXLoggerSecurityInformationLine.NDXLoggerSecurityInformationTable = nDXLoggerSecurityInformationTable.RecId;
    nDXLoggerSecurityInformationLine.LogActivity = argsLogger.parmLogActivity();
    nDXLoggerSecurityInformationLine.Counter = argsLogger.parmCounter();
    nDXLoggerSecurityInformationLine.insert();

    userConnection.ttscommit();
}

/// <summary>
/// PaffH 10.12.21
/// </summary>
/// <param name = "_argsLogger">NDXArgsLoggerSecuritiyInformation</param>
void LogLineChange(NDXIArgsLogger _argsLogger)
{
    NDXArgsLoggerSecuritiyInformation argsLogger = _argsLogger as NDXArgsLoggerSecuritiyInformation;
    userConnection.ttsbegin();

    nDXLoggerSecurityInformationLine.setConnection(userConnection);
    nDXLoggerSecurityInformationLine.Counter = argsLogger.parmCounter();
    nDXLoggerSecurityInformationLine.update();

    userConnection.ttscommit();
}
